/// The engine class a bare call to `name` resolves against, if any.
pub fn imported_class(name: &str) -> Option<&'static str> {
    let n = name.to_ascii_lowercase();
    IMPORTED.iter().find(|(f, _)| *f == n).map(|(_, c)| *c)
}
